    /// <summary>
    /// Pixel shader VACÍO de la pasada de sombras (ver README-SOMBRAS.md): en OpenGL no hay "pasada
    /// sin etapa de fragmentos" como en Direct3D 12 y Vulkan, así que el programa necesita un FS que
    /// no haga nada. No sale del HLSL porque no hay nada que traducir: la profundidad la escriben las
    /// etapas fijas del pipeline.
    /// </summary>
    internal const string EmptyPixelShader = "#version 430\nvoid main() { }";

    /// <summary>Unidad de textura del atlas de detalle (el mismo número en las cuatro APIs).</summary>
    internal const uint DetailTextureUnit = 2;

    /// <summary>Unidad de textura del arreglo de materiales (un Texture2DArray con todos los materiales).</summary>
    internal const uint MaterialTextureUnit = 6;

    /// <summary>Unidad de textura del shadow map (un sampler2DShadow con el comparador del hardware).</summary>
    internal const uint ShadowTextureUnit = 8;

    /// <summary>Binding del búfer con los píxeles de la franja de métricas (un storage buffer).</summary>
    internal const uint OverlayBufferBinding = 3;

    // Locations de los atributos del vertex shader de la geometría. Salen de la MISMA
    // declaración que usa el SPIR-V de Vulkan: si el HLSL reordena sus entradas estos números
    // se mueven, y el VAO del backend tiene que seguir a quien los lee y no a un 0..6 a mano.
    internal const uint AttributePosition = 0;
    internal const uint AttributeNormal = 1;
    internal const uint AttributeTexCoord = 2;
    internal const uint AttributeInstance0 = 3;
    internal const uint AttributeInstance1 = 4;
    internal const uint AttributeInstance2 = 5;
    internal const uint AttributeInstance3 = 6;

    /// <summary>Descomprime el GLSL (son cientos de miles de caracteres en total).</summary>
    private static string DecodeText(string base64)
    {
        using var compressed = new MemoryStream(Convert.FromBase64String(base64));
        using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
        using var reader = new StreamReader(gzip, Encoding.UTF8);
        return reader.ReadToEnd();
    }
}
